DO $review$
DECLARE v jsonb; s public.est_source_review%rowtype; q public.questions%rowtype; k public.question_keys%rowtype; a jsonb; qid uuid;
BEGIN
 FOR v IN SELECT value FROM jsonb_array_elements($payload$[{"id": "est2-papers-2026-09-26:l1dec:q46", "old_status": "needs_source_repair", "status": "ready", "question_id": "609b780d-f26f-5b50-8f48-0ae9a20aa20d", "stem": "Smartphone sales were 72.29 million in 2011, 150.26 million in 2013, and 169.22 million in 2014. The percent increase from 2010 to 2011 was four times the percent increase from 2013 to 2014. Approximately how many million smartphones were sold in 2010?", "choices": [{"key": "A", "text": "14.458"}, {"key": "B", "text": "32.350"}, {"key": "C", "text": "48.042"}, {"key": "D", "text": "25.730"}, {"key": "E", "text": "71.520"}], "type": "mcq", "correct": "C", "explanation": "Let x be 2010 sales in millions. The later growth fraction is (169.22−150.26)/150.26 = 18.96/150.26. Thus (72.29−x)/x = 4(18.96/150.26). Solving gives x = 72.29/[1+4(18.96/150.26)] ≈ 48.042. The denominator for each percentage is the earlier year’s sales.", "topic": "Statistics, Probability & Data Analysis", "note": "Original source image decrypted, hash checked, and visually inspected. Replaced the defective choice C with the calculated value; all required chart values are explicitly transcribed into the stem.", "source_document": "EST II - Math Level 1 - December 2020.pdf", "source_page": 14}, {"id": "est2-papers-2026-09-26:l1dec:q50", "old_status": "needs_source_repair", "status": "ready", "question_id": "5e9f3e1f-daab-5b3d-abec-c687d2e8bc8f", "stem": "A is the center of a circle. Points B, C, and D lie on the circle, with C on the major arc BD. If the central angle BAD is 80°, what is the inscribed angle BCD?", "choices": [{"key": "A", "text": "38.96°"}, {"key": "B", "text": "40°"}, {"key": "C", "text": "45.02°"}, {"key": "D", "text": "60.13°"}, {"key": "E", "text": "90°"}], "type": "mcq", "correct": "B", "explanation": "Angle BAD subtends the minor arc BD, whose measure is 80°. Since C lies on the major arc, angle BCD intercepts that same minor arc. An inscribed angle equals half its intercepted arc, so angle BCD=80°/2=40°.", "topic": "Triangles, Trigonometry & Similarity", "note": "Original source image decrypted, hash checked, and visually inspected. Editorial repair: explicitly identified the center and changed the erroneous requested angle BCA to BCD, the inscribed angle drawn in the source. This is a corrected adaptation, not a claim that original BCA was determined.", "source_document": "EST II - Math Level 1 - December 2020.pdf", "source_page": 15}, {"id": "est2-papers-2026-09-26:l1june:q27", "old_status": "needs_source_repair", "status": "ready", "question_id": "5a73282b-5df0-5e11-932b-3da080f93302", "stem": "Which equation describes the inverse relation of \\(y=x^2-4x+4\\)? In the answer choices, x≥0.", "choices": [{"key": "A", "text": "\\(y=-4\\pm\\sqrt{x}\\)"}, {"key": "B", "text": "\\(y=-2\\pm\\sqrt{x}\\)"}, {"key": "C", "text": "\\(y=\\pm\\sqrt{x}\\)"}, {"key": "D", "text": "\\(y=2\\pm\\sqrt{x}\\)"}, {"key": "E", "text": "\\(y=4\\pm\\sqrt{x}\\)"}], "type": "mcq", "correct": "D", "explanation": "Complete the square: y=(x−2)². Interchange x and y to get x=(y−2)². Taking both square-root branches yields y=2±√x, for x≥0. This is an inverse relation; without a domain restriction on the original parabola it is not an inverse function.", "topic": "Functions, Transformations & Graphs", "note": "Original source image decrypted, hash checked, and visually inspected. Corrected “inverse function” to “inverse relation” and removed function notation from the two-branch choices.", "source_document": "EST II - Math Level 1 - June 2021.pdf", "source_page": 7}, {"id": "est2-papers-2026-09-26:l1june:q41", "old_status": "needs_source_repair", "status": "ready", "question_id": "fc01b0d9-f150-5bd5-ab52-4eb412b8d343", "stem": "For positive x and y, which expression is equivalent to \\(\\sqrt[3]{135x^5y^7}\\,\\sqrt{180x^3y}\\)?", "choices": [{"key": "A", "text": "\\(18x^3y^2\\sqrt[6]{5^5y^4x}\\)"}, {"key": "B", "text": "\\(18x^2y^3\\sqrt[6]{5^5y^5x}\\)"}, {"key": "C", "text": "\\(18x^2y^3\\sqrt[6]{5^5y^4x}\\)"}, {"key": "D", "text": "\\(18x^3y^2\\sqrt[6]{5^5y^5x^2}\\)"}, {"key": "E", "text": "\\(18x^3y^2\\sqrt[6]{5^5y^5x}\\)"}], "type": "mcq", "correct": "E", "explanation": "Use a common root index of 6: the product is the sixth root of (135x⁵y⁷)²(180x³y)³. Since 135=3³·5 and 180=2²·3²·5, this radicand is 2⁶·3¹²·5⁵·x¹⁹·y¹⁷. Extract sixth powers to obtain 18x³y²·(5⁵xy⁵)^(1/6). Positivity makes the extraction valid without absolute values.", "topic": "Algebra Foundations, Equations & Inequalities", "note": "Original source image decrypted, hash checked, and visually inspected. Added the required positivity assumptions; the original statement fails for some negative inputs.", "source_document": "EST II - Math Level 1 - June 2021.pdf", "source_page": 11}, {"id": "est2-papers-2026-09-26:l1may:q10", "old_status": "needs_source_repair", "status": "ready", "question_id": "43a5129b-ccdb-5252-bddf-efd3bba8f00c", "stem": "A right circular cone is cut into two equal halves by a plane through its axis. The curved part of the surface of one half has three times the curved surface area of a hemisphere of radius 8 cm. What is the lateral surface area of the original cone?", "choices": [{"key": "A", "text": "768π cm²"}, {"key": "B", "text": "512π cm²"}, {"key": "C", "text": "384π cm²"}, {"key": "D", "text": "192π cm²"}, {"key": "E", "text": "128π cm²"}], "type": "mcq", "correct": "A", "explanation": "A hemisphere’s curved area is 2πr²=2π(8²)=128π. Half the cone’s curved surface is 3(128π)=384π, so the whole cone’s lateral area is 2(384π)=768π cm². The base and the flat cut faces are not included.", "topic": "Triangles, Trigonometry & Similarity", "note": "Original source image decrypted, hash checked, and visually inspected. Clarified lateral area and the axial cut, resolving the original ambiguous use of “area”.", "source_document": "EST II - Math Level 1 - May 2021.pdf", "source_page": 5}, {"id": "est2-papers-2026-09-26:l1may:q11", "old_status": "needs_source_repair", "status": "ready", "question_id": "6b2fb270-3b63-5e81-8abd-dd6a4e237a16", "stem": "Let a and b be positive real numbers with a≠b. For real t, what curve is represented by x=a sin t and y=b cos t?", "choices": [{"key": "A", "text": "Circle"}, {"key": "B", "text": "Ellipse"}, {"key": "C", "text": "Straight line"}, {"key": "D", "text": "Parabola"}, {"key": "E", "text": "Hyperbola"}], "type": "mcq", "correct": "B", "explanation": "Dividing gives x/a=sin t and y/b=cos t. Squaring and adding yields x²/a²+y²/b²=1. Positive a and b give an ellipse with nonzero semiaxes; a≠b makes it noncircular.", "topic": "Functions, Transformations & Graphs", "note": "Original source image decrypted, hash checked, and visually inspected. Added positive parameters to exclude the original circle and degenerate exceptions.", "source_document": "EST II - Math Level 1 - May 2021.pdf", "source_page": 5}]$payload$::jsonb) LOOP
  SELECT * INTO s FROM public.est_source_review WHERE id=v->>'id' FOR UPDATE;
  IF s.id IS NULL THEN RAISE EXCEPTION 'Missing source %',v->>'id'; END IF;
  IF EXISTS(SELECT 1 FROM public.audit_log WHERE action='source_review_20260928' AND target_id=s.id) THEN CONTINUE; END IF;
  IF s.review_status<>v->>'old_status' THEN RAISE EXCEPTION 'Source status changed %',s.id; END IF;
  qid=nullif(v->>'question_id','')::uuid;
  IF qid IS NOT NULL AND EXISTS(SELECT 1 FROM public.exams e JOIN public.attempts t ON t.exam_id=e.id
      WHERE qid=ANY(e.question_ids) AND t.status='in_progress' AND t.deadline_at>now()) THEN
   INSERT INTO public.audit_log(action,target_type,target_id,meta) VALUES('source_review_deferred_20260928','source_review',s.id,jsonb_build_object('reason','Active exam','proposed',v));
   CONTINUE;
  END IF;
  SELECT * INTO q FROM public.questions WHERE id=qid FOR UPDATE;
  SELECT * INTO k FROM public.question_keys WHERE question_id=qid FOR UPDATE;
  IF q.id IS NOT NULL AND v ? 'before' AND
    (q.stem IS DISTINCT FROM v->'before'->>'stem' OR q.choices IS DISTINCT FROM v->'before'->'choices' OR
     k.correct IS DISTINCT FROM v->'before'->'correct' OR k.explanation IS DISTINCT FROM v->'before'->>'explanation') THEN
    RAISE EXCEPTION 'Concurrent live question change %',qid;
  END IF;
  INSERT INTO public.audit_log(action,target_type,target_id,meta) VALUES('source_review_20260928','source_review',s.id,
    jsonb_build_object('before_source',to_jsonb(s),'before_question',to_jsonb(q),'before_key',to_jsonb(k),'decision',v-'assets'-'before'));
  IF v->>'status'='ready' THEN
   IF v->>'type'='mcq' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(v->'choices') c WHERE c->>'key'=v->'correct'#>>'{}') THEN RAISE EXCEPTION 'Invalid key %',s.id; END IF;
   IF v->>'type'='grid_in' AND NOT public.answer_matches('grid_in',CASE WHEN jsonb_typeof(v->'correct')='array' THEN v->'correct'->0 ELSE v->'correct' END,v->'correct') THEN RAISE EXCEPTION 'Grader rejects %',s.id; END IF;
   a=(coalesce(q.assets,'{}'::jsonb)-'release_hold_reason')||coalesce(v->'assets','{}'::jsonb)||jsonb_build_object(
    'verified_release','2026-09-28-independent-solution-and-source-check','answer_review','2026-09-28-independent-solution-and-source-check',
    'verification_note',v->>'note','source_review_id',s.id,'verification_source',s.source_document||' page '||s.source_page);
   IF q.id IS NULL THEN
    a=a||jsonb_build_object('source','reviewed-bank-20260928','source_code',s.source_code,'source_document',s.source_document,'source_page',s.source_page);
    INSERT INTO public.questions(id,track_id,topic,difficulty,type,stem,choices,assets)
     VALUES(qid,s.track_id,v->>'topic','medium',v->>'type',v->>'stem',v->'choices',a);
    INSERT INTO public.question_keys(question_id,correct,explanation) VALUES(qid,v->'correct',v->>'explanation');
   ELSE
    UPDATE public.questions SET topic=v->>'topic',type=v->>'type',stem=v->>'stem',choices=v->'choices',assets=a WHERE id=qid;
    UPDATE public.question_keys SET correct=v->'correct',explanation=v->>'explanation' WHERE question_id=qid;
   END IF;
  END IF;
  UPDATE public.est_source_review SET review_status=v->>'status',question_id=coalesce(qid,question_id),
   worked_answer=coalesce(v->'correct',worked_answer),duplicate_of=coalesce(v->>'duplicate_of',duplicate_of),
   review_note='Rechecked 2026-09-28. '||coalesce(v->>'note','')||CASE WHEN v ? 'explanation' THEN E'\nWorked solution: '||(v->>'explanation') ELSE '' END,
   updated_at=now() WHERE id=s.id;
 END LOOP;
END;
$review$;
SELECT count(*) applied_source_decisions FROM public.audit_log WHERE action='source_review_20260928';
